(() => {
  const question = document.getElementById('original-question');
  const dialog = document.getElementById('chart-dialog');
  const original = question?.querySelector('.chart-detail img');
  const slug = location.pathname.replace(/\/(?:index\.html)?$/, '').split('/').at(-1);
  if (!original || !dialog || !Object.hasOwn(charts, slug)) return;

  const [width, height, regions] = charts[slug];
  const views = [['完整原图', 0, 0, width, height], ...regions];
  const imageUrl = original.src;
  const svgNS = 'http://www.w3.org/2000/svg';

  function imageView(index) {
    const [label, x, y, w, h] = views[index];
    const svg = document.createElementNS(svgNS, 'svg');
    svg.setAttribute('viewBox', [x, y, w, h].join(' '));
    svg.setAttribute('width', w);
    svg.setAttribute('height', h);
    svg.setAttribute('role', 'img');
    svg.setAttribute('aria-label', label);
    const image = document.createElementNS(svgNS, 'image');
    image.setAttribute('href', imageUrl);
    image.setAttribute('width', width);
    image.setAttribute('height', height);
    svg.append(image);
    return svg;
  }

  function button(label) {
    const element = document.createElement('button');
    element.type = 'button';
    element.textContent = label;
    return element;
  }

  const form = dialog.querySelector('form');
  const modalTitle = document.createElement('strong');
  const zoom = document.createElement('select');
  zoom.setAttribute('aria-label', '图表缩放比例');
  for (const [value, label] of [['1', '适应窗口'], ['1.5', '放大 150%'], ['2', '放大 200%']]) {
    zoom.add(new Option(label, value));
  }
  const full = button('完整原图');
  full.dataset.modalFull = '';
  form.prepend(modalTitle, zoom, full);
  const viewport = document.createElement('div');
  viewport.className = 'task1-chart-viewport';
  viewport.tabIndex = 0;
  viewport.setAttribute('aria-label', '图表大图，可滚动查看');
  dialog.querySelector('img').replaceWith(viewport);
  dialog.classList.add('task1-chart-dialog');

  function resize() {
    const graphic = viewport.firstElementChild;
    if (graphic) graphic.style.width = Number(zoom.value) * 100 + '%';
  }

  function openView(index) {
    modalTitle.textContent = views[index][0];
    full.hidden = index === 0;
    zoom.value = '1';
    viewport.replaceChildren(imageView(index));
    viewport.scrollTop = 0;
    viewport.scrollLeft = 0;
    resize();
    if (!dialog.open) dialog.showModal();
  }

  full.addEventListener('click', () => openView(0));
  zoom.addEventListener('change', resize);

  function upgrade(panel) {
    if (!panel) return;
    panel.classList.add('task1-question');
    if (panel.querySelector('.task1-chart-tabs')) return;
    const detail = panel.querySelector('.chart-detail');
    if (!detail) return;
    const tabs = document.createElement('div');
    tabs.className = 'task1-chart-tabs';
    tabs.setAttribute('role', 'group');
    tabs.setAttribute('aria-label', '查看原题局部图');
    for (const [index, [label]] of views.entries()) {
      const tab = button(label);
      tab.dataset.chartView = index;
      tabs.append(tab);
    }
    detail.before(tabs);
    showView(panel, 0);
  }

  function showView(panel, index) {
    const detail = panel.querySelector('.chart-detail');
    for (const tab of panel.querySelectorAll('[data-chart-view]')) {
      tab.setAttribute('aria-pressed', String(Number(tab.dataset.chartView) === index));
    }
    const preview = button('');
    preview.className = 'task1-chart-preview';
    preview.dataset.chartZoom = index;
    preview.setAttribute('aria-label', '放大查看 ' + views[index][0]);
    preview.append(imageView(index));
    detail.replaceChildren(preview);
  }

  document.addEventListener('click', event => {
    const action = event.target.closest('[data-chart-view], [data-chart-zoom], .task1-question .full-chart');
    if (!action) return;
    if (action.matches('.full-chart')) openView(0);
    else if (action.dataset.chartZoom !== undefined) openView(Number(action.dataset.chartZoom));
    else showView(action.closest('.task1-question'), Number(action.dataset.chartView));
  });

  function preparePanels() {
    upgrade(question);
    document.querySelectorAll('.question-side-copy').forEach(upgrade);
  }
  preparePanels();
  window.addEventListener('hashchange', preparePanels);
})();
